int partition(List<int> a, int lo, int hi) {
  final pivot = a[hi];
  var store = lo;
  for (var i = lo; i < hi; i++) {
    if (a[i] < pivot) {
      final t = a[i];
      a[i] = a[store];
      a[store] = t;
      store++;
    }
  }
  final t = a[store];
  a[store] = a[hi];
  a[hi] = t;
  return store;
}

