(List<int>, int) sortCount(List<int> a) {
  if (a.length <= 1) return (a, 0);
  final mid = a.length ~/ 2;
  final (l, x) = sortCount(a.sublist(0, mid));
  final (r, y) = sortCount(a.sublist(mid));
  final out = <int>[];
  var i = 0, j = 0, c = 0;
  while (i < l.length && j < r.length) {
    if (l[i] <= r[j]) {
      out.add(l[i++]);
    } else {
      c += l.length - i;
      out.add(r[j++]);
    }
  }
  out
    ..addAll(l.sublist(i))
    ..addAll(r.sublist(j));
  return (out, x + y + c);
}

void main() {
  print(sortCount([3, 1, 2]).$2);
}
